function copyRoll(roll) {
  return roll.constructor.fromData(foundry.utils.deepClone(roll.toJSON()));
}
function refreshRoll(roll) {
  for (const term of roll.terms) {
    if (term.roll) refreshRoll(term.roll);
    for (const inner of term.rolls ?? []) refreshRoll(inner);
    for (const inner of term.terms ?? []) if (inner?.terms) refreshRoll(inner);
  }
  roll._total = roll._evaluateTotal();
  return roll;
}
function weaponDice(roll, workflow) {
  if (workflow.item?.type !== "weapon" || !workflow.activity?.damage?.includeBase) return [];
  const part = workflow.activity.damage.parts[0];
  if (!part) return [];
  const formula = part.formula ?? part.custom?.formula;
  if (!formula) return [];
  const base = foundry.dice.Roll.create(formula, workflow.activity.getRollData());
  return roll.dice.slice(0, base.dice.length);
}
async function rerollLowWeaponDice(roll, workflow) {
  const properties = workflow.item?.system?.properties;
  if (workflow.activity?.actionType !== "mwak" || workflow.attackMode !== "twoHanded"
    || !["two", "ver"].some(key => properties?.has(key))) return false;
  let changed = false;
  for (const die of weaponDice(roll, workflow)) {
    if (die.options.dnd5e_classpackGreatWeaponFighting) continue;
    die.options.dnd5e_classpackGreatWeaponFighting = true;
    changed = true;
    for (const result of [...die.results]) {
      if (!result.active || result.result > 2) continue;
      const replacement = new die.constructor({ number: 1, faces: die.faces });
      await replacement.evaluate();
      result.active = false;
      result.rerolled = true;
      die.results.push(...replacement.results);
    }
  }
  if (changed) refreshRoll(roll);
  return changed;
}

if (args[0]?.macroPass !== "postDamageRoll" || !workflow.damageRolls?.length) return;
if (workflow._classpackGreatWeaponDone) return;
workflow._classpackGreatWeaponDone = true;
const rolls = [...workflow.damageRolls];
const revised = copyRoll(rolls[0]);
if (await rerollLowWeaponDice(revised, workflow)) {
  rolls[0] = revised;
  await workflow.setDamageRolls(rolls);
}
